import styled from "styled-components";
import React, {useRef, useState, useEffect} from "react";
import classNames from "classnames";
import "../../styles/WordButton.css";

export const WordButton = ({
	backgroundColor = null,
	primary = true,
	label,
	size = "medium",
}) => {
	const [isActive, setIsActive] = useState(true);
	const [answerList, setAnswerList] = useState([]);

	const putAnswer = (value) => {
		setAnswerList((prevItem) => {
			const newItems = prevItem.includes(value)
				? [...prevItem, value]
				: prevItem.filter((i) => i !== value); // 제거

			console.log("즉시 변경된 리스트:", newItems); // 변경된 값 즉시 확인
			return newItems;
		});
	};
	const toggle = () => {
		setIsActive(!isActive);
	};
	const mode = isActive ? "word-button--primary" : "word-button--secondary";
	return (
		<button
			type="button"
			className={
				isActive
					? ["word-button", `word-button--${size}`, mode].join(" ")
					: ["word-button", `word-button--${size}`, mode].join(" ")
			}
			onClick={() => {
				console.log(label);
				toggle();
				putAnswer(label);
				console.log(isActive);
			}}
		>
			{label}
		</button>
	);
};

export default WordButton;
